css:
@media print {
    *,
    *:before,
    *:after {
        color: inherit !important;
        text-shadow: none !important;
        background: #fff !important;
        -webkit-box-shadow: none !important;
        box-shadow: none !important;
    }
}

.wrapper {
    position: relative;
}

.form-print-wrapper .page-break {
    position: relative;
}

.print-format {
    font-family: "europa", sans-serif;
    font-weight: 200;
    font-size: 11px;
    line-height: 1.42857143;
    color: #555 !important;
}


table {
    font-size: 12px;
    line-height: 1.42857143;
}

.text-wrap {
    word-wrap: break-word;
}

.print-format th,
.print-format strong {
    color: #333 !important;
}
.footer-section {
    font-family: "europa", sans-serif;
    font-weight: 300;
}

.print-heading {
    border: 0;
    text-align: center;
    font-family: "europa";
    font-weight: 300;
    padding: 0;
    text-transform: none;
    margin-top: -10px;
    position: relative;
}

.print-heading h2,
.print-heading h4 {
    display: inline-block;
    color: #333 !important;
    font-weight: 400;
    width: 500px;
}

.docname {
    font-size: 11px;
    color: #777 !important;
    float: left;
    position: absolute;
    top: 10px;
  left: 5px;
  width: 120px;
}

.page-number {
    position: absolute;
    right: 10px;
    top: 10px;
    display: inline-block;
    font-size: 11px;
    color: #777 !important;
}

.references-table,
.transporter-table {
    width: 100%;
}

.references-table {
    margin-bottom: 16px;
}

.references-table td,
.transporter-table td {
    padding: 1px !important;
}

.references-table td:nth-child(2) {
    padding: 1px 6px !important;
}

.references-table td.text-right {
    width: 35%;
}

.items th {
    vertical-align: middle !important;
    text-align: center;
}

.totals {
    width: 100%;
}

.totals th {
    font-weight: normal;
}

.totals td,
.totals th {
    background: none !important;
    padding: 3px !important;
}

.totals td {
    text-align: right;
}

.payment-area p {
    margin-bottom: 15px;
}

.fa {
    width: 14px;
    margin-right: 5px;
    text-align: center;
}

.tc-properties {
    font-size: 12px;
}

.tc-properties td,
.tc-properties th {
    padding: 4px !important;
}
